import { ProductEventPipeline } from "../dataModels/ProductEvent";

export interface TopProductsView {
  productId: string;
  viewCount: number;
  cartCount: number;
  purchaseCount: number;
  totalRevenue: number;
}

const sourceTable = ProductEventPipeline.table!;

export const TopProductsMV = new MaterializedView<TopProductsView>({
  tableName: "TopProductsView",
  materializedViewName: "top_products_mv",
  orderByFields: ["totalRevenue", "productId"],
  selectStatement: sql.statement`
    SELECT
      productId,
      countIf(eventType = 'view') as viewCount,
      countIf(eventType = 'cart') as cartCount,
      countIf(eventType = 'purchase') as purchaseCount,
      sumIf(JSONExtractFloat(properties, 'price'), eventType = 'purchase') as totalRevenue
    FROM ${sourceTable}
    GROUP BY productId
  `,
  selectTables: [sourceTable]
});

